function renderTokenChart(sessions,projectId){const days=[];const today=new Date();today.setHours(0,0,0,0);for(let index=teacherPreferences.overview_days-1;index>=0;index--){const date=new Date(today);date.setDate(today.getDate()-index);days.push({date,value:0})}for(const session of sessions){if(projectId!=='all'&&session.project_id!==projectId)continue;const date=new Date(session.started_at);date.setHours(0,0,0,0);const day=days.find(item=>item.date.getTime()===date.getTime());if(day)day.value+=session.total_tokens||0}const width=780,height=210,left=42,right=18,top=18,bottom=30,innerWidth=width-left-right,innerHeight=height-top-bottom,max=Math.max(...days.map(day=>day.value),1);const points=days.map((day,index)=>{const x=left+(index/(days.length-1))*innerWidth;const y=top+innerHeight-(day.value/max)*innerHeight;return {x,y,value:day.value,date:day.date}});const line=points.map(point=>point.x+','+point.y).join(' ');const area=left+','+(top+innerHeight)+' '+line+' '+(left+innerWidth)+','+(top+innerHeight);const grid=[0,.5,1].map(ratio=>{const y=top+innerHeight-(ratio*innerHeight);return '<line class="chart-grid" x1="'+left+'" x2="'+(left+innerWidth)+'" y1="'+y+'" y2="'+y+'"/><text class="chart-label" x="0" y="'+(y+4)+'">'+Math.round(max*ratio).toLocaleString()+'</text>'}).join('');const labels=points.filter((_,index)=>index%Math.max(1,Math.round(teacherPreferences.overview_days/5))===0||index===points.length-1).map(point=>'<text class="chart-label" text-anchor="middle" x="'+point.x+'" y="'+(height-7)+'">'+point.date.toLocaleDateString(undefined,{month:'short',day:'numeric'})+'</text>').join('');const dots=points.map(point=>'<circle class="chart-dot" cx="'+point.x+'" cy="'+point.y+'" r="3.5"><title>'+point.date.toLocaleDateString()+': '+point.value.toLocaleString()+' tokens</title></circle>').join('');el('token-chart').innerHTML='<svg class="chart" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Token usage over the last '+teacherPreferences.overview_days+' days"><defs><linearGradient id="tokenGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="var(--accent-strong)"/><stop offset="100%" stop-color="var(--accent-strong)" stop-opacity="0"/></linearGradient></defs>'+grid+'<polygon class="chart-area" points="'+area+'"/><polyline class="chart-line" points="'+line+'"/>'+dots+labels+'</svg>'}
